  "restatements": [
    {
      "clause_id": "Prop 40 Sec. 4 §37",
      "text": "Amends the California Constitution to authorize a one-time tax on the personal wealth and property of billionaires, creating a specialized reserve fund for the revenue that is exempt from state constitutional spending limits."
    },
    {
      "clause_id": "Prop 40 Sec. 5 §16355",
      "text": "Allocates 90 percent of the tax revenues to a health care account and 10 percent to an education and food assistance account, and provides an initial $50 million loan to the Franchise Tax Board for administration."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50301",
      "text": "Imposes a 5 percent excise tax on the net worth of applicable residents whose net worth is $1 billion or more for the 2026 tax year."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50303",
      "text": "Establishes valuation methods for various asset classes, specifically exempting directly-held real property and establishing reporting requirements for privately held businesses and trusts."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50304",
      "text": "Allows taxpayers whose tax liability exceeds the value of their publicly traded assets to open an Optional Deferral Account, deferring the tax payment until the assets are withdrawn or distributed."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50309",
      "text": "Exempts the Franchise Tax Board from the standard Administrative Procedure Act rulemaking process for this tax until 2028."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50312",
      "text": "Imposes penalties of up to 40 percent for gross understatements of tax liability and grants the Franchise Tax Board the authority to disregard transactions that lack economic substance."
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50314",
      "text": "Mandates an expedited judicial validation process for the act, requiring any challenges to be filed within 60 days in Sacramento County Superior Court, with direct appeal to the California Supreme Court."
    }
  ],
