  "analysis": [
    {
      "clause_id": "Prop 40 Sec. 6 §50301",
      "question_id": "Q1",
      "answer": "Current law was not provided, but generally California does not impose a state wealth tax. This measure creates a one-time 5% excise tax on the net worth of residents exceeding $1 billion.",
      "disputed": false
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50303",
      "question_id": "Q2",
      "answer": "Billionaires and their trusts will incur significant compliance costs, such as obtaining certified appraisals for privately held businesses, intellectual property, and other non-liquid assets to comply with the new reporting standards.",
      "disputed": false
    },
    {
      "clause_id": "Prop 40 Sec. 5 §16355",
      "question_id": "Q3",
      "answer": "The costs fall exclusively on roughly 200 California billionaires. The primary beneficiaries are lower-income individuals receiving Medi-Cal, safety net hospitals, public school districts, and food assistance programs.",
      "disputed": false
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50301",
      "question_id": "Q4",
      "answer": "Wealthy individuals may attempt to avoid the tax by changing their state of residence before January 1, 2026, reallocating their portfolios into exempt asset classes like directly-held real estate, or initiating litigation to challenge the constitutionality of the tax.",
      "disputed": false
    },
    {
      "clause_id": "Prop 40 Sec. 2",
      "question_id": "Q5",
      "answer": "The text asserts that federal funding cuts threaten Medi-Cal, education, and food programs, while noting that billionaires pay a disproportionately low effective tax rate on their accumulating wealth. The mechanism addresses this by levying a one-time massive wealth tax dedicated strictly to backfilling those specific shortfalls.",
      "disputed": false
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50309",
      "question_id": "Q6",
      "answer": "The Franchise Tax Board gains significant discretionary and rulemaking power because it is temporarily exempt from the Administrative Procedure Act and is authorized to redefine tax consequences by disregarding transactions it determines lack \"economic substance.\"",
      "disputed": false
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50301",
      "question_id": "Q7",
      "answer": "The effect of state-level wealth taxes on the residency of the ultra-wealthy is disputed. Some researchers find that highly concentrated taxes on the wealthy lead to significant out-migration and capital flight, ultimately eroding the tax base. Other researchers find that billionaires are highly tied to their primary residence state due to business, social, and cultural networks, making actual out-migration in response to tax hikes statistically marginal.",
      "disputed": true
    },
    {
      "clause_id": "Prop 40 Sec. 5 §16355",
      "question_id": "Q8",
      "answer": "Administration will be costly due to the intensive auditing and appraisal checks required for private assets, evidenced by the authorization of up to $50 million as a start-up loan for the Franchise Tax Board to build out the enforcement apparatus.",
      "disputed": false
    },
    {
      "clause_id": "Prop 40 Sec. 6 §50310",
      "question_id": "Q9",
      "answer": "The measure includes an amendment restriction requiring a two-thirds vote in the Legislature, and any amendment must be consistent with and further the purposes of the Act.",
      "disputed": false
    }
  ],
